import { useEffect, useState } from 'react';
import { getTasks } from '../../api';
import type { Task } from '../../types';
import './TaskBoard.css';

const SKELETON_COUNT = 3;

function TaskSkeleton(): React.ReactElement {
  return (
    <li className="task-board-item task-board-skeleton">
      <span className="task-board-skeleton-title">&nbsp;</span>
    </li>
  );
}

function TaskItem({ task }: { task: Task }): React.ReactElement {
  return (
    <li className="task-board-item">
      <span className="task-board-item-title">{task.title}</span>
      <span className="task-board-item-status">{task.status}</span>
    </li>
  );
}

export function TaskBoard(): React.ReactElement {
  const [tasks, setTasks] = useState<Task[] | null>(null);

  useEffect(() => {
    getTasks()
      .then((data) => {
        setTasks(data);
      })
      .catch(() => {
        setTasks([]);
      });
  }, []);

  const isLoading = tasks === null;
  const isEmpty = !isLoading && tasks.length === 0;
  const count = isLoading ? 0 : tasks.length;

  return (
    <section className="task-board">
      <header className="task-board-header">
        <h2 className="task-board-heading">
          Tasks
          <span className="task-board-badge" aria-label={`${count} tasks`}>
            {count}
          </span>
        </h2>
      </header>
      <div className="task-board-filter" role="search" aria-label="Filter tasks" />
      <ul className="task-board-list" aria-label="Tasks">
        {isLoading
          ? Array.from({ length: SKELETON_COUNT }, (_, i) => (
              <TaskSkeleton key={i} />
            ))
          : null}
        {!isLoading && !isEmpty
          ? tasks.map((task) => <TaskItem key={task.id} task={task} />)
          : null}
      </ul>
      {isEmpty ? (
        <p className="task-board-empty">No tasks found.</p>
      ) : null}
    </section>
  );
}
